/bin/bash -lc "python - <<'PY'
import numpy as np
# Numerical physical model, no rendering of candidate at this stage.
def simulate(m):
 p=np.array([[78.9,76.8],[66.35,94.0]],float);v=np.array([[-5.8,15.7],[0,0.]],float);mass=np.array([m,1]);rad=np.array([5.5,5.1]);dt=1/160;hit=False;land=False;wall=False; tr={20:p.copy()}
 for k in range(1,76*160):
  v[0,1]+=2.3*dt
  if hit:
   v[0,0]-=np.clip(v[0,0],-.30*dt,.30*dt)
   v[1,0]*=np.exp(-.137*dt);v[1,0]-=np.clip(v[1,0],-.149*dt,.149*dt)
  p+=v*dt
  for j in range(2):
   floor=99.2-rad[j]
   if p[j,1]>floor:
    p[j,1]=floor
    if j==0:v[j,1]=-v[j,1]*.46 if v[j,1]>1 else 0
    else:v[j,1]=0
  d=p[0]-p[1];dist=np.linalg.norm(d);n=d/dist
  if dist<sum(rad) and not hit:
   vn=np.dot(v[0]-v[1],n)
   if vn<0:
    J=-1.5*vn/(1/m+1);v[0]+=J/m*n;v[1]-=J*n
    p[0]+=n*(sum(rad)-dist);hit=True
    print('collision',m,'t',20+k*dt,'normal',n,'vel',v.copy())
  if p[0,0]>158.5 and p[0,1]>84:
   p[0,0]=158.5
   if v[0,0]>0:v[0,0]*=-.4;wall=True;print('wall',m,20+k*dt)
  if k%160==0:tr[20+k//160]=p.copy()
 return tr
for m in [.68,.17]:
 tr=simulate(m)
 print('mass',m, [(i,np.round(tr[i],2).tolist()) for i in [21,22,23,24,26,28,30,32,34,38,45,60,95]])
PY"
